if(!email){markInvalid('email','emailErr','Email address is required.');valid=false;}
else if(!emailRe.test(email)){markInvalid('email','emailErr','Please enter a valid email address.');valid=false;}
if(dob){var d=new Date(dob);var now=new Date();if(isNaN(d.getTime())||d>now){markInvalid('dob','dobErr','Date of birth must be in the past.');valid=false;}}
if(!pw){markInvalid('password','pwErr','Password is required.');valid=false;}
else if(pw.length<8){markInvalid('password','pwErr','Password must be at least 8 characters.');valid=false;}
if(!confirm){markInvalid('confirm','confirmErr','Please confirm your password.');valid=false;}
else if(pw&&confirm!==pw){markInvalid('confirm','confirmErr','Passwords do not match.');valid=false;}
if(!tos){setError('tosErr','You must accept the Terms of Service.');valid=false;}
if(!valid)return;
if(isDuplicate(username,email)){
var users=getUsers();var un=username.toLowerCase();var em=email.toLowerCase();
var dupField='';
if(users.some(function(u){return u.username===un;}))dupField='username';
if(users.some(function(u){return u.email===em;}))dupField=dupField?'both':'email';
if(dupField==='username'||dupField==='both')markInvalid('username','usernameErr','This username is already registered.');
if(dupField==='email'||dupField==='both')markInvalid('email','emailErr','This email is already registered.');
return;
}
saveUser({username:username.toLowerCase(),email:email.toLowerCase(),dob:dob||null,registeredAt:new Date().toISOString()});
successMsg.textContent='Registration successful! Welcome, '+username+'.';
successMsg.hidden=false;
form.reset();
document.querySelectorAll('.toggle-pw').forEach(function(b){var t=document.getElementById(b.getAttribute('data-target'));if(t)t.type='password';b.textContent='Show';});
});
})();
</script>
</body>
</html>
