<script>
(function(){
var STORAGE_KEY='registered_users_v1';
function getUsers(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||[];}catch(e){return[];}}
function saveUser(u){var users=getUsers();users.push(u);localStorage.setItem(STORAGE_KEY,JSON.stringify(users));}
function isDuplicate(username,email){var users=getUsers();var un=username.toLowerCase().trim();var em=email.toLowerCase().trim();return users.some(function(u){return u.username===un||u.email===em;});}
function setError(id,msg){var el=document.getElementById(id);if(el)el.textContent=msg;}
function clearErrors(){document.querySelectorAll('.error-msg').forEach(function(e){e.textContent='';});document.querySelectorAll('.invalid').forEach(function(e){e.classList.remove('invalid');});}
function markInvalid(inputId,errId,msg){var inp=document.getElementById(inputId);if(inp)inp.classList.add('invalid');setError(errId,msg);}
document.querySelectorAll('.toggle-pw').forEach(function(btn){
btn.addEventListener('click',function(){
var target=document.getElementById(btn.getAttribute('data-target'));
if(!target)return;
var showing=target.type==='text';
target.type=showing?'password':'text';
btn.textContent=showing?'Show':'Hide';
btn.setAttribute('aria-label',showing?'Show '+btn.getAttribute('aria-label').replace('Hide ',''):'Hide '+btn.getAttribute('aria-label').replace('Show ',''));
target.focus();
});
});
var form=document.getElementById('regForm');
var successMsg=document.getElementById('successMsg');
form.addEventListener('submit',function(e){
e.preventDefault();
clearErrors();
successMsg.hidden=true;
var valid=true;
var username=document.getElementById('username').value.trim();
var email=document.getElementById('email').value.trim();
var dob=document.getElementById('dob').value;
var pw=document.getElementById('password').value;
var confirm=document.getElementById('confirm').value;
var tos=document.getElementById('tos').checked;
if(!username||username.length<3){markInvalid('username','usernameErr','Username must be at least 3 characters.');valid=false;}
else if(!/^[a-zA-Z0-9_]+$/.test(username)){markInvalid('username','usernameErr','Username may only contain letters, numbers, and underscores.');valid=false;}
var emailRe=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if(!email){markInvalid('email','emailErr','Email address is required.');valid=false;}
else if(!emailRe.test(email)){markInvalid('email','emailErr','Please enter a valid email address.');valid=false;}
if(dob){var d=new Date(dob);var now=new Date();if(isNaN(d.getTime())||d>now){markInvalid('dob','dobErr','Date of birth must be in the past.');valid=false;}}
if(!pw){markInvalid('password','pwErr','Password is required.');valid=false;}
else if(pw.length<8){markInvalid('password','pwErr','Password must be at least 8 characters.');valid=false;}
if(!confirm){markInvalid('confirm','confirmErr','Please confirm your password.');valid=false;}
else if(pw&&confirm!==pw){markInvalid('confirm','confirmErr','Passwords do not match.');valid=false;}
if(!tos){setError('tosErr','You must accept the Terms of Service.');valid=false;}
if(!valid)return;
if(isDuplicate(username,email)){
var users=getUsers();var un=username.toLowerCase();var em=email.toLowerCase();
var dupField='';
if(users.some(function(u){return u.username===un;}))dupField='username';
if(users.some(function(u){return u.email===em;}))dupField=dupField?'both':'email';
if(dupField==='username'||dupField==='both')markInvalid('username','usernameErr','This username is already registered.');
if(dupField==='email'||dupField==='both')markInvalid('email','emailErr','This email is already registered.');
return;
}
saveUser({username:username.toLowerCase(),email:email.toLowerCase(),dob:dob||null,registeredAt:new Date().toISOString()});
successMsg.textContent='Registration successful! Welcome, '+username+'.';
successMsg.hidden=false;
form.reset();
document.querySelectorAll('.toggle-pw').forEach(function(b){var t=document.getElementById(b.getAttribute('data-target'));if(t)t.type='password';b.textContent='Show';});
});
})();
</script>
